#!/usr/bin/env python3
"""DAY329 [KERNEL-HOMOGENEO-D329] DEBT-LAB-KERNEL-HOMOGENEO-001, commit 2 de 2: arrancar y comprobar el kernel.

Nuevos: scripts/emecas/con_limite.pl (tiempo límite que mata el grupo de procesos), kernel_homogeneo.sh,
kernel_homogeneo_vm.sh y test_kernel_homogeneo.sh. Makefile: el paso vagrant-up de EMECAS en tres (up solo con
apt-espera y debian-fecha, reload, provision), los pasos kernel-homogeneo y test-kernel-homogeneo, y sus targets.
Requiere d329_debian_fecha.py aplicado (usa all.yml y lab_comun.rb).

Uso (Mac, raíz del repo): python3 -I scripts/etcd_ha/d329_kernel_homogeneo.py [--apply]
Sin --apply solo comprueba. Con --apply escribe, y solo si TODO cuadra: sha256 de partida de cada fichero que modifica,
cada ancla exactamente las veces esperadas y ningún fichero nuevo ya existente. Si algo falla no escribe nada.
"""
import hashlib, os, sys

NUEVOS = {'scripts/emecas/con_limite.pl': ('#!/usr/bin/perl\n# [KERNEL-HOMOGENEO-D329] (anfitrión) con_limite.pl <segundos> <orden> [args...]: ejecuta la orden con tiempo límite.\n# La orden va en su propio grupo de procesos y, si vence el límite, se mata el GRUPO entero (TERM y, a los 2 s, KILL) y\n# sale con 142. Un alarm sobre vagrant solo no basta: su ssh hijo sigue vivo con la salida abierta y quien lee esa\n# salida se queda esperando (medido DAY329 en test_kernel_homogeneo.sh: 61 s con un límite de 10). Sin la orden: 127.\n# Si la orden muere por una señal: 128 + señal; si no, su código de salida.\nuse strict;\nuse warnings;\nmy $lim = shift @ARGV;\ndie "uso: con_limite.pl <segundos> <orden> [args...]\\n" unless defined $lim && $lim =~ /\\A[1-9][0-9]*\\z/ && @ARGV;\nmy $pid = fork();\ndie "con_limite.pl: fork: $!\\n" unless defined $pid;\nif ($pid == 0) {\n  setpgrp(0, 0);\n  exec { $ARGV[0] } @ARGV;\n  exit 127;\n}\n$SIG{ALRM} = sub {\n  kill \'TERM\', -$pid;\n  sleep 2;\n  kill \'KILL\', -$pid;\n  waitpid($pid, 0);\n  exit 142;\n};\nalarm $lim;\nwaitpid($pid, 0);\nalarm 0;\nmy $st = $?;\nexit(($st & 127) ? 128 + ($st & 127) : $st >> 8);\n', 493), 'scripts/emecas/kernel_homogeneo.sh': ('#!/bin/bash\n# [KERNEL-HOMOGENEO-D329] (anfitrión) DEBT-LAB-KERNEL-HOMOGENEO-001: todas las VMs del laboratorio en el mismo Debian\n# y ejecutando su kernel. Para cada VM, con el tiempo límite de all.yml en cada llamada (una VM que no contesta es ❌, no\n# un cuelgue: lección DAY328; con_limite.pl mata también los hijos de vagrant):\n#   - fecha: sus fuentes de Debian apuntan a argus_debian_snapshot;\n#   - kernel: uname -r es el kernel que pide linux-image-amd64 en esa fecha (instalado y ADEMÁS arrancado);\n#   - el mismo kernel en todas las VMs.\n# Uso: kernel_homogeneo.sh <all.yml> <vm>...   rc 0 solo si todas cumplen. Coste lineal en el número de VMs.\n# KERNEL_HOMOGENEO_VAGRANT: el vagrant a usar (por defecto, vagrant; el test pone uno falso).\nset -u\nD=$(cd "$(dirname "$0")" && pwd)\nY=${1:?uso: kernel_homogeneo.sh <all.yml> <vm>...}\nshift\n[ "$#" -ge 1 ] || { echo "❌ kernel-homogeneo: sin VMs que comprobar"; exit 1; }\nVAGRANT=${KERNEL_HOMOGENEO_VAGRANT:-vagrant}\n\nFECHA=$(ruby "$D/lab_comun.rb" fecha "$Y") || { echo "❌ kernel-homogeneo: sin argus_debian_snapshot válido en $Y"; exit 1; }\nLIM=$(ruby "$D/lab_comun.rb" limite "$Y") || { echo "❌ kernel-homogeneo: no se puede leer el límite de $Y"; exit 1; }\necho "[KERNEL-HOMOGENEO-D329] fecha declarada $FECHA; límite por llamada ${LIM} s; $# VMs"\n\nmalas=0\nprimero=""\nfor vm in "$@"; do\n  T0=$(date +%s)\n  salida=$(perl "$D/con_limite.pl" "$LIM" "$VAGRANT" ssh "$vm" -- \'bash -s\' < "$D/kernel_homogeneo_vm.sh" 2>/dev/null)\n  rc=$?\n  dt=$(( $(date +%s) - T0 ))\n  if [ "$rc" -eq 142 ]; then\n    echo "  ❌ $vm: no contesta en ${LIM} s (cortado por el límite)"; malas=$((malas + 1)); continue\n  fi\n  u=$(printf \'%s\\n\' "$salida" | sed -n \'s/^uname=//p\' | head -n 1)\n  f=$(printf \'%s\\n\' "$salida" | sed -n \'s/^fecha=//p\' | head -n 1)\n  k=$(printf \'%s\\n\' "$salida" | sed -n \'s/^kernel_fecha=//p\' | head -n 1)\n  if [ "$rc" -ne 0 ] || [ -z "$u" ]; then\n    echo "  ❌ $vm: la consulta falló (rc=$rc, ${dt} s)"; malas=$((malas + 1)); continue\n  fi\n  fallos=""\n  [ "$f" = "$FECHA" ] || fallos="$fallos fecha=${f:-<ninguna>} (declarada $FECHA);"\n  [ "$u" = "$k" ] || fallos="$fallos uname=$u no es el kernel de la fecha (${k:-<ninguno>});"\n  [ -z "$primero" ] && primero="$u"\n  [ "$u" = "$primero" ] || fallos="$fallos uname=$u distinto del de las demás ($primero);"\n  if [ -z "$fallos" ]; then\n    echo "  ✅ $vm: $u, fecha $f (${dt} s)"\n  else\n    echo "  ❌ $vm:$fallos"; malas=$((malas + 1))\n  fi\ndone\n\nif [ "$malas" -eq 0 ]; then\n  echo "✅ kernel-homogeneo: $# VMs en $FECHA con el kernel $primero"\n  exit 0\nfi\necho "❌ kernel-homogeneo: $malas de $# VMs no cumplen"\nexit 1\n', 493), 'scripts/emecas/kernel_homogeneo_vm.sh': ('#!/bin/bash\n# [KERNEL-HOMOGENEO-D329] (dentro de cada VM; lo envía kernel_homogeneo.sh por stdin) tres líneas clave=valor:\n#   uname         kernel en marcha\n#   fecha         marca de snapshot.debian.org de bookworm-security en /etc/apt/sources.list (vacía si no hay)\n#   kernel_fecha  kernel que pide linux-image-amd64 instalado (el de la fecha tras debian-fecha)\nset -u\necho "uname=$(uname -r)"\necho "fecha=$(sed -n \'s#^deb .*snapshot\\.debian\\.org/archive/debian-security/\\([0-9]\\{8\\}T[0-9]\\{6\\}Z\\)/ bookworm-security .*#\\1#p\' /etc/apt/sources.list 2>/dev/null | head -n 1)"\necho "kernel_fecha=$(dpkg-query -W -f=\'${Depends}\' linux-image-amd64 2>/dev/null | sed -n \'s/.*linux-image-\\([0-9][^ ,]*\\).*/\\1/p\' | head -n 1)"\n', 493), 'scripts/emecas/test_kernel_homogeneo.sh': ('#!/bin/bash\n# [KERNEL-HOMOGENEO-D329] test de kernel_homogeneo.sh (anfitrión) con un vagrant falso: cada VM responde lo que diga su\n# fichero en el directorio temporal, o se cuelga. Comprueba el código de salida, el veredicto de cada VM y, en la VM\n# colgada, que el límite la corta (un examinador sin límite convierte un rojo en silencio: DAY328).\nset -u\nD=$(cd "$(dirname "$0")" && pwd)\nT=$(mktemp -d)\ntrap \'rm -rf "$T"\' EXIT\nF=20261115T000000Z\nK=6.1.0-54-amd64\nLIM=10   # el mínimo de all.yml: la VM colgada cuesta 10 s\n\ncat > "$T/vagrant" <<\'FALSO\'\n#!/bin/bash\n# vagrant falso: "ssh <vm> -- bash -s"; responde con $KH_DIR/vm_<vm>, o se cuelga si contiene "colgar"\ncat > /dev/null\nr="$KH_DIR/vm_$2"\n[ -f "$r" ] || exit 1\nif grep -qx colgar "$r"; then sleep 60; exit 0; fi\ncat "$r"\nFALSO\nchmod +x "$T/vagrant"\nexport KH_DIR="$T" KERNEL_HOMOGENEO_VAGRANT="$T/vagrant"\n\nprintf \'argus_debian_snapshot: "%s"\\nargus_lab_llamada_vm_limite_s: %s\\n\' "$F" "$LIM" > "$T/all.yml"\nprintf \'argus_lab_llamada_vm_limite_s: %s\\n\' "$LIM" > "$T/sin_fecha.yml"\nbien() { printf \'uname=%s\\nfecha=%s\\nkernel_fecha=%s\\n\' "${1:-$K}" "${2:-$F}" "${3:-$K}" > "$T/vm_$4"; }\n\nfallos=0\ncasos=0\ncomprobar() {  # nombre rc_esperado patrón_obligatorio n_ok_esperado -- args\n  local nombre=$1 rc_esp=$2 patron=$3 nok=$4; shift 5\n  local s rc n\n  s=$(bash "$D/kernel_homogeneo.sh" "$@" 2>&1); rc=$?\n  n=$(printf \'%s\\n\' "$s" | grep -c \'^  ✅\')\n  casos=$((casos + 1))\n  if [ "$rc" -eq "$rc_esp" ] && printf \'%s\\n\' "$s" | grep -q -- "$patron" && [ "$n" -eq "$nok" ]; then\n    echo "✅ $nombre"\n  else\n    echo "❌ $nombre (rc=$rc, esperado $rc_esp; ✅ por VM=$n, esperado $nok; patrón \'$patron\')"\n    printf \'%s\\n\' "$s" | sed \'s/^/     | /\'\n    fallos=$((fallos + 1))\n  fi\n}\n\nbien "" "" "" a; bien "" "" "" b; bien "" "" "" c\ncomprobar "tres VMs iguales y en la fecha" 0 "✅ kernel-homogeneo: 3 VMs" 3 -- "$T/all.yml" a b c\n\nbien 6.1.0-25-amd64 "" "" b\ncomprobar "una VM con el kernel de la caja (instalado el de la fecha, sin arrancar)" 1 "❌ b: uname=6.1.0-25-amd64 no es el kernel de la fecha" 2 -- "$T/all.yml" a b c\n\nbien "" 20261116T000000Z "" b\ncomprobar "una VM con otra fecha" 1 "❌ b: fecha=20261116T000000Z" 2 -- "$T/all.yml" a b c\n\nbien "" "" "" b; bien 6.1.0-55-amd64 "" 6.1.0-55-amd64 c\ncomprobar "una VM coherente consigo misma pero con otro kernel que las demás" 1 "distinto del de las demás" 2 -- "$T/all.yml" a b c\n\nbien "" "" "" c; echo colgar > "$T/vm_b"\nt0=$(date +%s)\ncomprobar "una VM que no contesta" 1 "❌ b: no contesta en ${LIM} s" 2 -- "$T/all.yml" a b c\ndt=$(( $(date +%s) - t0 )); casos=$((casos + 1))\nif [ "$dt" -lt $((LIM + 15)) ]; then echo "✅ el límite la corta (${dt} s)"; else echo "❌ el límite no la corta (${dt} s)"; fallos=$((fallos + 1)); fi\n\nbien "" "" "" b\ncomprobar "sin fecha declarada: para y no consulta ninguna VM" 1 "ERROR DE FABRICANTE" 0 -- "$T/sin_fecha.yml" a b c\n\ncomprobar "una VM que no existe" 1 "❌ z: la consulta falló" 1 -- "$T/all.yml" a z\n\necho "$((casos - fallos))/$casos casos"\n[ "$fallos" -eq 0 ]\n', 493)}

MODIFICA = {'Makefile': ('3bfc0e0ea208612cbbfe7c24882eac9136d2857aca714d39f911bf461398a689', [('\t@$(EMECAS_PASO) vagrant-up -- vagrant up defender client suricata zeek wazuh $(CONTROL_NODOS)\n', '\t@# [KERNEL-HOMOGENEO-D329] DEBT-LAB-KERNEL-HOMOGENEO-001 (decisión de Alonso DAY329): primero solo apt-espera y\n\t@# debian-fecha (Debian en la fecha de all.yml), luego un reinicio para arrancar el kernel de esa fecha (reload\n\t@# vuelve a montar /vagrant) y después el aprovisionamiento entero, ya sobre ese kernel. kernel-homogeneo lo comprueba\n\t@$(EMECAS_PASO) vagrant-up -- vagrant up --provision-with apt-espera,debian-fecha $(EMECAS_VMS)\n\t@$(EMECAS_PASO) vagrant-reload -- vagrant reload --no-provision $(EMECAS_VMS)\n\t@$(EMECAS_PASO) vagrant-provision -- vagrant provision $(EMECAS_VMS)\n\t@$(EMECAS_PASO) kernel-homogeneo -- $(MAKE) kernel-homogeneo\n', 1), ('\t@$(EMECAS_PASO) test-anfitrion-recursos -- $(MAKE) test-anfitrion-recursos\n', '\t@$(EMECAS_PASO) test-anfitrion-recursos -- $(MAKE) test-anfitrion-recursos\n\t@$(EMECAS_PASO) test-kernel-homogeneo -- $(MAKE) test-kernel-homogeneo\n', 1), ('test-anfitrion-recursos:\n\t@python3 -I scripts/emecas/test_recursos_anfitrion.py\n', 'test-anfitrion-recursos:\n\t@python3 -I scripts/emecas/test_recursos_anfitrion.py\n\n# [KERNEL-HOMOGENEO-D329] (Mac) DEBT-LAB-KERNEL-HOMOGENEO-001: todas las VMs del lab con sus fuentes de Debian en la\n# fecha de ansible/inventory/group_vars/all.yml y EJECUTANDO el kernel de esa fecha (uname -r), el mismo en todas; con\n# el tiempo límite de all.yml en cada llamada (scripts/emecas/con_limite.pl mata también los hijos de vagrant). Tras un\n# vagrant up a mano las VMs siguen en el kernel de la caja hasta un vagrant reload: esto lo dice. EMECAS_VMS: la lista\n# de VMs de EMECAS, una sola vez. test-kernel-homogeneo (Mac): el validador de all.yml y la comprobación con un vagrant\n# falso (kernel sin arrancar, otra fecha, otro kernel, VM colgada, sin fecha, VM inexistente).\n.PHONY: kernel-homogeneo test-kernel-homogeneo\nEMECAS_VMS = defender client suricata zeek wazuh $(CONTROL_NODOS)\nkernel-homogeneo:\n\t@bash scripts/emecas/kernel_homogeneo.sh ansible/inventory/group_vars/all.yml $(EMECAS_VMS)\n\ntest-kernel-homogeneo:\n\t@ruby scripts/emecas/test_lab_comun.rb\n\t@bash scripts/emecas/test_kernel_homogeneo.sh\n', 1)])}

def main():
    aplicar = "--apply" in sys.argv[1:]
    if not os.path.isfile("Vagrantfile") or not os.path.isfile("Makefile"):
        sys.exit("❌ ejecutar desde la raíz del repo")
    errores, resultado = [], {}
    for ruta in NUEVOS:
        if os.path.exists(ruta):
            errores.append("ya existe " + ruta)
    for ruta, (sha_partida, cambios) in MODIFICA.items():
        datos = open(ruta, "rb").read()
        h = hashlib.sha256(datos).hexdigest()
        if h != sha_partida:
            errores.append("%s: sha256 de partida %s, esperado %s" % (ruta, h, sha_partida))
            continue
        texto = datos.decode("utf-8")
        for viejo, nuevo, veces in cambios:
            n = texto.count(viejo)
            if n != veces:
                errores.append("%s: ancla %d veces, esperadas %d: %r" % (ruta, n, veces, viejo[:90]))
            else:
                texto = texto.replace(viejo, nuevo)
        resultado[ruta] = texto
    if errores:
        print("❌ no se escribe nada:")
        for e in errores:
            print("   - " + e)
        sys.exit(1)
    if not aplicar:
        print("✅ todo cuadra (sin --apply no se escribe nada): %d nuevos, %d modificados" % (len(NUEVOS), len(resultado)))
        return
    for ruta, (contenido, modo) in NUEVOS.items():
        os.makedirs(os.path.dirname(ruta) or ".", exist_ok=True)
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(contenido)
        os.chmod(ruta, modo)
        print("  + %s  sha256=%s" % (ruta, hashlib.sha256(contenido.encode()).hexdigest()))
    for ruta, texto in resultado.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("  ~ %s  sha256=%s" % (ruta, hashlib.sha256(texto.encode()).hexdigest()))
    print("✅ aplicado")

if __name__ == "__main__":
    main()
